"""Mechanical private initializer/program bridge and independent complete oracle.

NEW unexecuted r2. The private error controls use the first immutable callback,
prior to any own GROW; complete source and old drafts are preserved separately.
Actual HIA owns framing, bounds, receipts, Graph import and values. Python only
owns byte buffers, process lifecycle and observational evidence. Namespace
physical effects and eight remaining initializer kinds remain foreign.
"""
BODY="\nimport importlib.util\nimport signal\nimport subprocess\n\nPROGRAM_BRIDGE_ROOT=Path(os.environ['HIA_PROGRAM_BRIDGE_ROOT']).resolve()\nPROGRAM_BUNDLE_PATH=Path(os.environ['HIA_PROGRAM_BUNDLE']).resolve()\nPROGRAM_EXE=None\nPROGRAM_EXE_SHA=None\nPROGRAM_PARENT=os.getpid()\nPROGRAM_COUNTS=dict(processes=0)\nPROGRAM_RESULTS=[]\nPROGRAM_CAPTURES=[]\nPROGRAM_CAPTURE=False\nPROGRAM_CAPTURE_SCOPE=None\nPROGRAM_CAPTURED_KEYS=set()\nPB_CONSTANTS=None\nprogram_previous_peer=peer\nprogram_original_get=NativeRegistry.get\nprogram_previous_check=check\n\n# Only the independent reference owns Python VerifiedProgram and assembly.\n# It runs before native entry. An isolated module keeps the renderer's internal\n# roundtrip from hitting the outer constructor's observation wrapper.\nPROGRAM_REFERENCE_VERIFY=service.verify_program\nprogram_reference_path=REFERENCE/'hepta/hia_agent_assembly.py'\nprogram_reference_raw=read(program_reference_path)\nprogram_reference_name='hepta._worker_program_initializer_reference_assembly'\nprogram_reference_spec=importlib.util.spec_from_file_location(program_reference_name,program_reference_path)\nPROGRAM_REFERENCE_ASSEMBLY=importlib.util.module_from_spec(program_reference_spec)\nsys.modules[program_reference_name]=PROGRAM_REFERENCE_ASSEMBLY\nprogram_reference_spec.loader.exec_module(PROGRAM_REFERENCE_ASSEMBLY)\nprogram_oracle_tree=ast.parse(oracle_raw)\nprogram_oracle_node=copy.deepcopy(next(n for n in program_oracle_tree.body\n    if isinstance(n,ast.FunctionDef) and n.name=='oracle'))\nprogram_oracle_replacements=ast.parse(\"\"\"\ndef verified(document):\n    checked=PROGRAM_REFERENCE_VERIFY(document)\n    result=Program(checked.as_dict(),checked.sha256)\n    result._reference_checked=checked\n    examples['document']=copy.deepcopy(document)\n    observe('verify',document,result)\n    return result\ndef rendered(program):\n    text=PROGRAM_REFERENCE_ASSEMBLY.render_assembly(program._reference_checked)\n    observe('render',program,text)\n    examples['assembly']=text\n    return text\ndef assembled(text):\n    checked=PROGRAM_REFERENCE_ASSEMBLY.assemble_program(text)\n    result=Program(checked.as_dict(),checked.sha256)\n    result._reference_checked=checked\n    observe('assemble',text,result)\n    return result\n\"\"\").body\nprogram_replace_map={n.name:n for n in program_oracle_replacements}\nprogram_original_nested={n.name:n for n in program_oracle_node.body if isinstance(n,ast.FunctionDef)}\nassert set(program_replace_map)<=set(program_original_nested)\nprogram_oracle_node.name='program_actual_reference_oracle'\nprogram_oracle_node.body=[program_replace_map.get(n.name,n) if isinstance(n,ast.FunctionDef) else n\n    for n in program_oracle_node.body]\nprogram_oracle_node.body.insert(0,ast.parse(\"assert mismatch is False\").body[0])\nexec(compile(ast.fix_missing_locations(ast.Module(body=[program_oracle_node],type_ignores=[])),\n    '<exact-original-Service-oracle-with-real-program-assembly>','exec'),globals())\nlegacy_initializer_oracle=program_actual_reference_oracle\n\ndef program_registry_get(self,token,kind='value'):\n    if kind=='program' and token>HANDLE_BASE:\n        assert token in self.c.get('program_observations',{})\n        return self.c['program_observations'][token]\n    return program_original_get(self,token,kind)\nNativeRegistry.get=program_registry_get\n\ndef load_program_components():\n    global PROGRAM_EXE,PROGRAM_EXE_SHA,PB_CONSTANTS\n    bundle=json.loads(read(PROGRAM_BRIDGE_ROOT/'development/compile-r1/bundle.json'))\n    assert bundle['schema']=='hia-worker-initializer-program-bridge-v1' and bundle['status']=='PASS'\n    assert bundle['compiler_sha256']==COMPILER_SHA\n    assert set(bundle['components'])=={'program-input','program-output','program-decoder','program-datagraph'}\n    for role,row in bundle['components'].items():\n        source=read(row['source_path']);image=read(row['image_path'])\n        receipt=json.loads(read(row['receipt_path']))\n        assert (len(source),digest(source))==(row['source_bytes'],row['source_sha256'])\n        assert (len(image),digest(image))==(row['image_bytes'],row['image_sha256'])\n        assert receipt['image_sha256']==COMPILER_SHA\n        assert receipt['input_sha256']==digest(source) and receipt['produced_sha256']==digest(image)\n        DH.frozen(Path(row['source_path']),row['source_sha256'])\n        DH.frozen(Path(row['image_path']),row['image_sha256'])\n        DH.frozen(Path(row['receipt_path']))\n        DH.images[role]=NativeHiaJsonImage(image,digest(image))\n    input_spec=json.loads(read(PROGRAM_BRIDGE_ROOT/'development/input-source-r1.json'))\n    output_spec=json.loads(read(PROGRAM_BRIDGE_ROOT/'development/output-source-r1.json'))\n    assert input_spec['constants']==output_spec['constants']\n    PB_CONSTANTS=input_spec['constants']\n    for spec in (input_spec,output_spec):\n        for path,row in spec['source_dependencies'].items():\n            raw=read(path)\n            assert (len(raw),digest(raw),Path(path).stat().st_mode&4095)==(\n                row['bytes'],row['sha256'],row['mode'])\n    for row in json.loads(read(PROGRAM_BRIDGE_ROOT/'development/compile-r1/source-pins.json')):\n        raw=read(row['path'])\n        assert (len(raw),digest(raw),stat.S_IMODE(Path(row['path']).stat().st_mode))==(\n            row['bytes'],row['sha256'],row['mode'])\n    actual=json.loads(read(PROGRAM_BUNDLE_PATH))\n    assert actual['status']=='BUILT_ONLY' and actual['fresh_compiles']==6\n    assert actual['nonzero_images']==41 and actual['compiler_sha256']==COMPILER_SHA\n    PROGRAM_EXE=Path(actual['executable_path']).resolve()\n    executable=read(PROGRAM_EXE)\n    assert (len(executable),digest(executable))==(actual['executable_bytes'],actual['executable_sha256'])\n    assert stat.S_IMODE(PROGRAM_EXE.stat().st_mode)&0o111\n    PROGRAM_EXE_SHA=digest(executable)\n    # The fixed program bundle carries every immutable input/source/image pin.\n    # The frozen builder additionally proves all tables, padding and ELF bytes.\n    manifest=json.loads(read(PROGRAM_BUNDLE_PATH.parent/'source-pins.json'))\n    assert isinstance(manifest,list) and manifest\n    for row in manifest:\n        raw=read(row['path']);frozen=read(row['frozen'])\n        assert raw==frozen and (len(raw),digest(raw))==(row['bytes'],row['sha256'])\n        assert stat.S_IMODE(Path(row['path']).stat().st_mode)==row['mode']\n        assert stat.S_IMODE(Path(row['frozen']).stat().st_mode)==row['mode']\n    save(OUT/'program-components.json',dict(bridge=bundle,program=actual,\n        program_reference_module=dict(path=str(program_reference_path),sha256=digest(program_reference_raw)),\n        complete_original_constructor_oracle=True,physical_namespace_foreign=True))\n    save(OUT/'source-before.json',rows())\n    DH.OUT.joinpath('source-before.json').write_text(json.dumps(DH.pins,sort_keys=True,indent=2)+'\\n')\n\ndef program_child_setup():\n    resource.setrlimit(resource.RLIMIT_CPU,(90,90))\n    resource.setrlimit(resource.RLIMIT_AS,(1<<30,1<<30))\n    resource.setrlimit(resource.RLIMIT_CORE,(0,0))\n    libc=ctypes.CDLL(None,use_errno=True)\n    libc.prctl.argtypes=[ctypes.c_int]+[ctypes.c_ulong]*4\n    libc.prctl.restype=ctypes.c_int\n    if libc.prctl(4,0,0,0,0)!=0 or libc.prctl(3,0,0,0,0)!=0:os._exit(125)\n    if libc.prctl(1,signal.SIGKILL,0,0,0)!=0 or os.getppid()!=PROGRAM_PARENT:os._exit(125)\n\ndef program_actual_child(packet,label):\n    ordinal=PROGRAM_COUNTS['processes']+1\n    root=OUT/'program-processes'/('%04d-'%ordinal+label)\n    root.mkdir(parents=True,exist_ok=False)\n    (root/'input.bin').write_bytes(packet)\n    save(OUT/'pending-program-process.json',dict(label=label,ordinal=ordinal,input=cas(packet),\n        executable_sha256=PROGRAM_EXE_SHA,limits=dict(cpu_seconds=90,wall_seconds=180,address_space_bytes=1<<30)))\n    process=None;timed=False;before=resource.getrusage(resource.RUSAGE_CHILDREN);start=time.monotonic_ns()\n    try:\n        with (root/'input.bin').open('rb') as fi,(root/'stdout.bin').open('wb') as fo,(root/'stderr.bin').open('wb') as fe:\n            process=subprocess.Popen([str(PROGRAM_EXE)],stdin=fi,stdout=fo,stderr=fe,\n                env={'PATH':'/nonexistent','HOME':'/nonexistent','LANG':'C.UTF-8','LC_ALL':'C.UTF-8'},\n                close_fds=True,start_new_session=True,preexec_fn=program_child_setup)\n            PROGRAM_COUNTS['processes']=ordinal\n            try:rc=process.wait(timeout=180)\n            except subprocess.TimeoutExpired:\n                timed=True;os.killpg(process.pid,signal.SIGKILL);rc=process.wait()\n    finally:\n        if process is not None and process.poll() is None:\n            os.killpg(process.pid,signal.SIGKILL);process.wait()\n    after=resource.getrusage(resource.RUSAGE_CHILDREN)\n    stdout=(root/'stdout.bin').read_bytes();stderr=(root/'stderr.bin').read_bytes()\n    result=dict(label=label,ordinal=ordinal,returncode=rc,timed_out=timed,\n        wall_ns=time.monotonic_ns()-start,user_cpu=after.ru_utime-before.ru_utime,\n        system_cpu=after.ru_stime-before.ru_stime,input=cas(packet),stdout=cas(stdout),stderr=cas(stderr),\n        executable_sha256=PROGRAM_EXE_SHA,parent_cleanup_complete=True,\n        empty_PATH_and_HOME=True,no_host_semantic_callback=True)\n    save(root/'process.json',result)\n    assert not timed and rc in (0,2),result\n    return rc,stdout,stderr,result\n\ndef program_decoder_call(s,r,w,label):\n    # Decoder is R/W/W. This is a distinct mechanical contract, never a SHA alias.\n    role='program-decoder';before=(s.raw(),r.raw(),w.raw())\n    number=DH.counts.get(role,0)+1;DH.counts[role]=number\n    pending=dict(role=role,entry=number,label=label,s=DH.save(before[0]),\n        r=DH.save(before[1]),w=DH.save(before[2]),actual_abi='RWW')\n    (DH.OUT/'pending.json').write_text(json.dumps(pending,sort_keys=True)+'\\n')\n    result=int(DH.images[role]._entry(s.memory,s.n,r.memory,r.n,w.memory,w.n))\n    s.check();r.check();w.check();assert s.raw()==before[0]\n    DH.log.write(json.dumps(dict(**pending,result=result,same_first_input=True,\n        after_r=DH.save(r.raw()),after_w=DH.save(w.raw())),sort_keys=True)+'\\n');DH.log.flush()\n    return result\n\ndef program_command(c,route,mode,payload=b'',actual=0,role=0,extent=0,extra0=0,extra1=0):\n    source=c['g'].raw()\n    return pack(M(b'HIAWPBC1'),mode,37,83,route['lease'],route['seq'],\n        struct.unpack_from('<Q',source,8)[0],len(source),len(payload),actual,role,extent,extra0,extra1,0,0)+payload\n\ndef program_call(c,route,command,label):\n    source=DH.Buffer(c['g'].n,c['g'].raw())\n    second=DH.Buffer(len(command),command);before=route['w'].raw()\n    role={1:'program-input',2:'program-output'}[route['kernel']]\n    result=DH.invoke(role,source,second,route['w'],label)\n    event=struct.unpack_from('<32Q',route['w'].raw(),2048)\n    mode=struct.unpack_from('<Q',command,8)[0]\n    if PROGRAM_CAPTURE:\n        # Keep the first distinct boundary; full every-entry bytes remain in CAS.\n        key=(route['peer'],mode,event[1],event[6])\n        if key not in PROGRAM_CAPTURED_KEYS:\n            PROGRAM_CAPTURED_KEYS.add(key)\n            PROGRAM_CAPTURES.append(dict(label=label,mode=mode,role=role,kernel=route['kernel'],\n                source=source.raw(),command=command,workspace=before,after=route['w'].raw(),\n                result=result,event=event,peer=route['peer'],lease=route['lease'],\n                initializer=c['w'].raw(),initializer_source=c['s'].raw(),sequence=c['seq'],\n                child_packet=route.get('child_packet')))\n    assert result==2304,(label,result,event)\n    assert event[:5]==(M(b'HIAWPBE1'),event[1],37,83,route['lease'])\n    assert event[5]==route['seq']+1 and event[7]==0 and event[8]==route['pending']\n    assert event[9]==route['peer'] and event[10:12]==(53,4300) and event[31]==0\n    assert event[30] in (1,2)\n    route['seq']=event[5];route['kernel']=event[30];route['event']=event\n    route['last_command']=command\n    return event\n\ndef program_import(c,wire,packet,label):\n    fields=list(struct.unpack('<16Q',wire))\n    assert fields[1]==3 and fields[4]==c['active'] and fields[5]==c['bseq']\n    expected,payload=registry_command(c,3,packet,foreign_bytes=len(packet))\n    assert pack(*expected)==wire and payload==packet\n    c['foreign_raw']=packet;c['foreign_bytes']=len(packet)\n    reserved=c['pw'].raw()[512:768]\n    f,r=prepare_import(c,packet,label)\n    while True:\n        merge_actual(c,f,r,label)\n        f,r=merge_submit(c,label)\n        if f[1]==4:continue\n        assert f[1]==6\n        handle=adopt_import(c,f,r)\n        c['imports'].append(dict(ordinal=len(c['imports'])+1,label=label,\n            initializer_pending=c['f'][7],foreign_graph=cas(packet),\n            imported_graph=cas(c['g'].raw()),handle=handle,graph_root=f[20],\n            source_lease=struct.unpack_from('<Q',reserved,72)[0],\n            output_lease=struct.unpack_from('<Q',reserved,80)[0],\n            foreign_issuer=False,actual_program_result=True))\n        c['reg'].kinds[handle]='value'\n        return handle,c['pw'].raw()[512:768]\n\ndef program_grow(route,name,buffer,needed,staged=False):\n    assert needed>buffer.n,(name,needed,buffer.n)\n    key=name+'-first'\n    if staged and key not in route['shortened'] and needed-1>buffer.n:\n        route['shortened'].add(key);needed-=1\n    route['growth'].append(dict(owner=name,before=buffer.n,after=needed))\n    return buffer.grow(needed)\n\ndef native_program_route(c):\n    f=c['f'];assert f[1]==2 and f[6] in (16,17,18)\n    # The predecessor event is consumed before any observational BORROW.\n    initial=c['w'].raw();before=dict(DH.counts);outer=dict(entries)\n    route=dict(w=DH.Buffer(8192),seq=0,kernel=1,lease=1990000+f[7],\n        pending=f[7],peer=f[6],growth=[],shortened=set(),wire=None,dg=None,\n        imports=[],child_rows=[],decoder_calls=0,datagraph_calls=0,wire_calls=0)\n    payload=initial+c['pw'].raw()[512:768]\n    command=program_command(c,route,1,payload,2304,len(initial),768,256)\n    event=program_call(c,route,command,'program-begin-'+str(f[6]))\n    with ExitStack() as stack:\n        for target in ('hepta.hia_agent_service.verify_program','hepta.hia_program.verify_program',\n            'hepta.hia_agent_assembly.render_assembly','hepta.hia_agent_assembly.assemble_program',\n            'hepta.hia_agent_assembly._parse_assembly_document','json.loads'):\n            stack.enter_context(patch(target,new=disabled))\n        while True:\n            action=event[1]\n            if action==1:\n                # Retry the immutable callback only. Never call its producer twice.\n                route['w']=program_grow(route,'own',route['w'],event[12],c['growth']=='staged')\n                event=program_call(c,route,route['last_command'],'program-own-grow')\n                continue\n            if action==2:\n                assert event[13]==1 and event[15]==128\n                wire=route['w'].raw()[event[14]:event[14]+event[15]]\n                words=list(struct.unpack('<16Q',wire))\n                if words[1] in (2,6):\n                    assert words[4]==c['blast']+1 and words[5]==c['bseq']\n                    c['active']=words[4]\n                    rf,rr=registry_entry(c,words,b'','program-actual-registry-'+str(words[1]))\n                    assert rr.raw()==wire and rf[1]=={2:2,6:5}[words[1]]\n                    callback=2 if words[1]==6 else 5\n                    actual=c['pw'].raw()[512:768]\n                else:\n                    assert words[1]==3 and event[23]>0\n                    packet=route['w'].raw()[event[22]:event[22]+event[23]]\n                    handle,actual=program_import(c,wire,packet,'actual-program-graph-'+str(f[6]))\n                    route['imports'].append(handle);callback=8\n                command=program_command(c,route,callback,actual,768,1,256)\n                event=program_call(c,route,command,'program-registry-response-'+str(callback))\n                continue\n            if action==3:\n                assert event[13] in (2,3) and event[15]==64 and event[16]==1\n                assert event[17]==0 and event[18]==c['g'].n and event[19]>=32768\n                if route['wire'] is None:\n                    assert event[21]==1;route['wire']=DH.Buffer(event[19])\n                else:\n                    assert event[21]==0\n                    if event[19]>route['wire'].n:\n                        route['wire']=program_grow(route,'wire',route['wire'],event[19],c['growth']=='staged')\n                wire=route['w'].raw()[event[14]:event[14]+event[15]]\n                source=DH.Buffer(c['g'].n,c['g'].raw());second=DH.Buffer(64,wire)\n                result=DH.invoke({2:'scan',3:'emit'}[event[13]],source,second,route['wire'],'program-actual-wire')\n                route['wire_calls']+=1\n                command=program_command(c,route,3,route['wire'].raw(),result,event[13],route['wire'].n)\n                event=program_call(c,route,command,'program-wire-response')\n                continue\n            if action==4:\n                assert event[13]==4 and event[15]>=64\n                packet=route['w'].raw()[event[14]:event[14]+event[15]]\n                route['child_packet']=packet\n                rc,stdout,stderr,row=program_actual_child(packet,'initializer-p'+str(f[6]))\n                route['child_rows'].append(row)\n                route['stdout']=stdout;route['stderr']=stderr;route['child_rc']=rc\n                command=program_command(c,route,4,stdout+stderr,rc,4,len(stdout),len(stderr))\n                event=program_call(c,route,command,'program-child-result')\n                continue\n            if action==5:\n                assert event[13]==5 and event[15]==64 and event[16]==3 and event[21]==1\n                raw=route['w'].raw()[event[17]:event[17]+event[18]]\n                config=route['w'].raw()[event[14]:event[14]+event[15]]\n                first=DH.Buffer(len(raw),raw);second=DH.Buffer(event[20])\n                scratch=DH.Buffer(event[19],config)\n                result=program_decoder_call(first,second,scratch,'program-actual-core-decoder')\n                route['decoder_calls']+=1\n                command=program_command(c,route,6,second.raw()+scratch.raw(),result,5,second.n,scratch.n)\n                event=program_call(c,route,command,'program-core-decoder-result')\n                continue\n            if action==6:\n                assert event[13]==6 and event[15]==128 and event[16]==3\n                source=route['w'].raw()[event[17]:event[17]+event[18]]\n                wire=route['w'].raw()[event[22]:event[22]+event[23]]\n                config=route['w'].raw()[event[14]:event[14]+event[15]]\n                if route['dg'] is None:\n                    assert event[21]==1\n                    fresh=bytearray(event[19]);fresh[128:256]=config\n                    route['dg']=DH.Buffer(len(fresh),bytes(fresh))\n                else:\n                    assert event[21]==0\n                    route['dg']=program_grow(route,'datagraph',route['dg'],event[19],False)\n                first=DH.Buffer(len(source),source);second=DH.Buffer(len(wire),wire)\n                result=DH.invoke('program-datagraph',first,second,route['dg'],'program-actual-core-datagraph')\n                route['datagraph_calls']+=1\n                command=program_command(c,route,7,route['dg'].raw(),result,6,route['dg'].n)\n                event=program_call(c,route,command,'program-core-datagraph-result')\n                continue\n            assert action==0 and event[6]==90 and event[29]>=256\n            reply=route['w'].raw()[event[28]:event[28]+event[29]]\n            q=struct.unpack_from('<32Q',reply)\n            assert q[:5]==(M(b'HIAWIR01'),37,83,f[7],f[6])\n            route['reply']=reply;route['reply_words']=q\n            break\n    assert c['w'].raw()==initial and entries['sequence']==outer['sequence']\n    assert len(route['child_rows'])==1\n    if route['child_rc']==0:\n        assert q[5]==0 and q[6]==(12 if f[6]==17 else 11) and len(reply)==256\n        assert q[7]==0 and q[11:15]==(0,0,0,0) and q[15]==256 and q[20:]==(0,)*12\n        assert list(q[8:10] if f[6]==17 else q[8:11])==route['imports']\n        assert route['decoder_calls']==(0 if f[6]==17 else 1)\n        assert route['datagraph_calls']==(0 if f[6]==17 else 3)\n    else:\n        assert q[5:7]==(1,0) and q[12]==route['lease']\n        assert q[13:16]==(256,len(reply)-256,len(reply))\n        assert reply[256:]==route['stderr'][128:]\n    route['entry_delta']={k:v-before.get(k,0) for k,v in DH.counts.items()}\n    return route\n\ndef native_program_peer(c,fail_at):\n    f=c['f'];before_programs=PROGRAM_COUNTS['processes']\n    route=native_program_route(c)\n    q=route['reply_words'];assert q[5]==0,'fixed initializer example must complete valid program route'\n    R=c['reg']\n    if f[6] in (16,18):\n        core=R.get(q[9]);hex_digest=R.get(q[10])\n        assert hex_digest==route['reply'][128:160].hex()\n        result=Program(core,hex_digest)\n        c.setdefault('program_observations',{})[q[8]]=result\n        c['reg'].kinds[q[8]]='program'\n        kind='verify' if f[6]==16 else 'assemble'\n        argument=R.get(f[14])\n        if f[6]==16:c['program_document']=copy.deepcopy(argument)\n    else:\n        kind='render';argument=R.get(f[14],'program');result=R.get(q[8])\n        c['reg'].kinds[q[9]]='bytes'\n        assert R.get(q[9],'bytes')==result.encode('utf-8')\n    if observe(c,kind,argument,result,fail_at):\n        c['r']=Buffer(len(route['reply']),route['reply']);c['reply_count']+=1\n    row=dict(peer=f[6],pending=f[7],reply=cas(route['reply']),input=cas(route['child_packet']),\n        stdout=cas(route['stdout']),stderr=cas(route['stderr']),process=route['child_rows'][0],\n        imported_handles=route['imports'],growth=route['growth'],wire_calls=route['wire_calls'],\n        actual_core_decoder_calls=route['decoder_calls'],actual_datagraph_calls=route['datagraph_calls'],\n        actual_native_entries=route['entry_delta'],complete_receipt_and_original_input_preserved=True,\n        actual_program_processes=PROGRAM_COUNTS['processes']-before_programs,\n        graph_values_imported_by_native_registry=True,namespace_authority=False)\n    PROGRAM_RESULTS.append(row);c.setdefault('program_results',[]).append(row)\n\ndef peer(c,fail_at,false_dirs,mismatch):\n    if c['f'][6] in (16,17,18):\n        assert mismatch is False\n        native_program_peer(c,fail_at)\n    else:program_previous_peer(c,fail_at,false_dirs,mismatch)\n\ndef program_check(label,paths=(),fail_at=None,false_dirs=(),growth='exact'):\n    before=PROGRAM_COUNTS['processes'];start=len(PROGRAM_RESULTS)\n    c=program_previous_check(label,paths,fail_at=fail_at,false_dirs=false_dirs,growth=growth)\n    actual=PROGRAM_RESULTS[start:]\n    expected_peers=[{'verify':16,'render':17,'assemble':18}[row['kind']]\n        for row in c['baseline']['trace'] if row['kind'] in ('verify','render','assemble')]\n    if fail_at in ('verify:0','render:0','assemble:0'):\n        expected_peers=expected_peers[:{'verify:0':1,'render:0':2,'assemble:0':3}[fail_at]]\n    assert [row['peer'] for row in actual]==expected_peers,(label,[r['peer'] for r in actual],expected_peers)\n    assert PROGRAM_COUNTS['processes']-before==len(actual)\n    assert all(r['actual_program_processes']==1 for r in actual)\n    if c['observed_error'] is None:\n        assert expected_peers==[16,17,18]\n        assert actual[0]['stdout']['bytes']>512 and actual[2]['stdout']['bytes']>512\n        assert c['program_observations'][actual[0]['imported_handles'][0]].sha256==c['program_observations'][actual[2]['imported_handles'][0]].sha256\n    save(OUT/'program-results.json',PROGRAM_RESULTS)\n    return c\n\ndef program_semantic_cases():\n    global planned,CATALOG\n    CATALOG=SMALL_CATALOG;planned=3\n    for label,paths in (\n        ('program-complete-empty',()),\n        ('program-complete-unicode',('/e\\u0301','/\\u4e2d','/emoji-\\U0001f642')),\n        ('program-complete-duplicates',('/same','/same'))):\n        program_check(label,paths)\n\ndef program_failure_cases():\n    global planned,CATALOG\n    CATALOG=SMALL_CATALOG;planned=3\n    for label in ('verify:0','render:0','assemble:0'):\n        c=program_check('program-observer-'+label.replace(':','-'),fail_at=label)\n        assert c['observed_error']==dict(error_class='PeerFailure',error=label,attributes={})\n    # The failures are explicit constructor-observer fixtures after the actual\n    # valid peer result, not invented program semantic failures.\n\ndef program_capacity_cases():\n    global planned,CATALOG\n    CATALOG=SMALL_CATALOG;planned=2\n    exact=program_check('program-capacity-exact',('/capacity',),growth='exact')\n    staged=program_check('program-capacity-staged',('/capacity',),growth='staged')\n    assert exact['trace']==staged['trace']\n    assert exact['observed_error']==staged['observed_error'] is None\n    assert len(exact['program_results'])==len(staged['program_results'])==3\n    for c in (exact,staged):\n        assert sum(len(r['growth']) for r in c['program_results'])>0\n        assert all(r['actual_program_processes']==1 for r in c['program_results'])\n        assert [r['actual_core_decoder_calls'] for r in c['program_results']]==[1,0,1]\n    assert sum(len(r['growth']) for r in staged['program_results'])>sum(\n        len(r['growth']) for r in exact['program_results'])\n\ndef program_replay(snapshot,label,mutator=None,role=None,advertised=None):\n    source=bytearray(snapshot['source']);command=bytearray(snapshot['command'])\n    workspace=bytearray(snapshot['workspace'])\n    if mutator is not None:mutator(source,command,workspace)\n    s=DH.Buffer(len(source),bytes(source));r=DH.Buffer(len(command),bytes(command))\n    w=DH.Buffer(len(workspace),bytes(workspace));chosen=role or snapshot['role']\n    before=dict(DH.counts)\n    if advertised is None:\n        result=DH.invoke(chosen,s,r,w,label)\n    else:\n        assert 0<=advertised<w.n\n        count=DH.counts.get(chosen,0)+1;DH.counts[chosen]=count\n        pending=dict(role=chosen,entry=count,label=label,advertised_workspace=advertised,\n            s=DH.save(s.raw()),r=DH.save(r.raw()),w=DH.save(w.raw()))\n        (DH.OUT/'pending.json').write_text(json.dumps(pending,sort_keys=True)+'\\n')\n        result=int(DH.images[chosen]._entry(s.memory,s.n,r.memory,r.n,w.memory,advertised))\n        s.check();r.check();w.check()\n        assert s.raw()==bytes(source) and r.raw()==bytes(command)\n        DH.log.write(json.dumps(dict(**pending,result=result,after_w=DH.save(w.raw()),\n            same_inputs=True),sort_keys=True)+'\\n');DH.log.flush()\n    return result,w,bytes(source),bytes(command),bytes(workspace),before\n\ndef program_fault(label,snapshot,mutator,poison=True,role=None,advertised=None):\n    before=dict(entries)\n    result,w,source,command,original,before_native=program_replay(snapshot,label,mutator,role,advertised)\n    assert result==BAD,(label,result,struct.unpack_from('<32Q',w.raw(),2048))\n    after=w.raw()\n    if poison:\n        valid_s=DH.Buffer(len(snapshot['source']),snapshot['source'])\n        valid_r=DH.Buffer(len(snapshot['command']),snapshot['command'])\n        assert DH.invoke(snapshot['role'],valid_s,valid_r,w,label+'-persistent')==BAD\n        assert w.raw()==after\n    else:assert after==original\n    record(label,before,dict(private_actual_frame_mutation=True,\n        full_source=cas(source),full_command=cas(command),full_before=cas(original),full_after=cas(after),\n        permanent_refusal=poison,short_workspace_must_retire=not poison,\n        additional_actual_entries={k:v-before_native.get(k,0) for k,v in DH.counts.items()},\n        forged_headers_not_source_authentication=True))\n\ndef program_actual_error_control(snapshot,source,label,reference):\n    \"\"\"Actual child rejection on a distinct private issued input.\n\n    This is an isolated protocol clone; it is not the unchanged constructor's\n    public document, and no success is attributed to a substituted input lease.\n    \"\"\"\n    before=dict(entries);before_native=dict(DH.counts)\n    packet=bytearray(snapshot['child_packet'][:64])\n    struct.pack_into('<Q',packet,32,len(source))\n    struct.pack_into('<Q',packet,48,0)\n    packet=bytes(packet)+source\n    rc,stdout,stderr,process=program_actual_child(packet,label)\n    assert rc==2 and not stdout and len(stderr)>384\n    payload=stdout+stderr\n    command=bytearray(snapshot['command'][:128])\n    struct.pack_into('<Q',command,64,len(payload))\n    struct.pack_into('<Q',command,72,rc)\n    struct.pack_into('<Q',command,88,len(stdout))\n    struct.pack_into('<Q',command,96,len(stderr))\n    command=bytes(command)+payload\n    private=dict(snapshot,command=command)\n    result,w,*_=program_replay(private,label+'-actual-native-error')\n    own_calls=1\n    while result==2304 and struct.unpack_from('<Q',w.raw(),2056)[0]==1:\n        event=struct.unpack_from('<32Q',w.raw(),2048)\n        w=w.grow(event[12])\n        s=DH.Buffer(len(private['source']),private['source']);r=DH.Buffer(len(command),command)\n        result=DH.invoke(private['role'],s,r,w,label+'-own-grow');own_calls+=1\n    event=struct.unpack_from('<32Q',w.raw(),2048)\n    assert result==2304 and event[1]==0 and event[6]==90\n    reply=w.raw()[event[28]:event[28]+event[29]]\n    q=struct.unpack_from('<32Q',reply)\n    assert q[:7]==(M(b'HIAWIR01'),37,83,event[8],event[9],1,0)\n    assert q[12:16]==(snapshot['lease'],256,len(stderr)-128,len(reply))\n    assert reply[256:]==stderr[128:]\n    frame=struct.unpack_from('<32Q',reply,256)\n    text=reply[256+frame[14]:256+frame[14]+frame[15]]\n    assert text==reference['message'] and frame[6]==reference['domain']\n    assert frame[7:9]==(reference['phase'],reference['line'])\n    first=Buffer(len(snapshot['initializer_source']),snapshot['initializer_source'])\n    second=Buffer(len(reply),reply)\n    iw=Buffer(len(snapshot['initializer']),snapshot['initializer'])\n    actual=invoke('sequence',first,second,iw,label+'-original-initializer-error')\n    f=struct.unpack_from('<32Q',iw.raw(),2048)\n    assert actual==2304 and f[1]==3 and f[4]==snapshot['sequence']+1\n    assert f[27:30]==(0,3,snapshot['lease']) and f[30:32]==(256,len(reply)-256)\n    assert second.raw()[f[30]:f[30]+f[31]]==stderr[128:]\n    record(label,before,dict(actual_native_program_error=True,actual_initializer_unwind=True,\n        isolated_private_input_differs_from_constructor=True,not_an_input_substitution_authentication_test=True,\n        original_source=cas(snapshot['child_packet']),issued_control_input=cas(packet),\n        actual_process=process,actual_error=cas(stderr[128:]),full_reply=cas(reply),\n        actual_after_initializer=cas(iw.raw()),own_calls=own_calls,\n        reference_error={**reference,'message':reference['message'].decode()},\n        additional_actual_entries={k:v-before_native.get(k,0) for k,v in DH.counts.items()}))\n\ndef program_protocol_cases():\n    global planned,CATALOG,PROGRAM_CAPTURE\n    CATALOG=SMALL_CATALOG\n    # Independent complete error references are fixed before native execution.\n    invalids={\n      16:b'\\xff',\n      17:b'{\"schema\":\"hepta.hia.composite.v1\",\"module\":\"private_representation\",\"types\":[],\"functions\":[{\"name\":\"identity\",\"params\":[{\"name\":\"value\",\"type\":\"u8\"}],\"returns\":[\"u8\"],\"effects\":[],\"entry\":\"entry\",\"blocks\":[{\"id\":\"entry\",\"params\":[{\"name\":\"value\",\"type\":\"u8\"}],\"ops\":[],\"term\":{\"op\":\"ret\",\"values\":[\"value\"]}}]}]}',\n      18:b'not assembly\\n'}\n    references={}\n    for peer,source in invalids.items():\n        try:\n            if peer==16:PROGRAM_REFERENCE_VERIFY(source)\n            elif peer==17:PROGRAM_REFERENCE_ASSEMBLY.render_assembly(source)\n            else:PROGRAM_REFERENCE_ASSEMBLY.assemble_program(source)\n        except Exception as exc:\n            assert isinstance(exc,PROGRAM_REFERENCE_ASSEMBLY.HIAProgramRejected)\n            is_assembly=isinstance(exc,PROGRAM_REFERENCE_ASSEMBLY.HIAAssemblyRejected)\n            references[peer]=dict(message=str(exc).encode(),domain=2 if is_assembly else 1,\n                phase={'syntax':1,'core_verification':2,'representation':3}.get(getattr(exc,'phase',None),0),\n                line=getattr(exc,'line',None) or 0)\n        else:raise AssertionError(('expected original rejection',peer))\n    PROGRAM_CAPTURE=True\n    try:c=program_check('program-actual-protocol-fixture')\n    finally:PROGRAM_CAPTURE=False\n    def find(peer,mode,action=None,phase=None):\n        selected=[r for r in PROGRAM_CAPTURES if r['peer']==peer and r['mode']==mode\n            and (action is None or r['event'][1]==action)\n            and (phase is None or r['event'][6]==phase)]\n        assert selected,(peer,mode,action,phase)\n        return selected[0]\n    begin=find(16,1);borrow=find(16,2);wire=find(16,3,4)\n    child=find(16,4,2);reserve=find(16,5,2,35)\n    decoded=find(16,6,6);dg=find(16,7,2,35);bound=find(16,8)\n    record_borrow=find(17,2,4)\n    faults=[]\n    def word(label,snapshot,at,value):\n        faults.append((label,snapshot,lambda s,r,w,at=at,value=value:struct.pack_into('<Q',r,at,value),True,None,None))\n    for label,at,value in (\n        ('magic',0,0),('invocation',16,0),('call',24,0),('route-lease',32,0),\n        ('route-lease-overflow',32,MAX),('first-sequence',40,1),\n        ('source-lease',48,0),('source-extent',56,len(begin['source'])+1),\n        ('payload-size',64,len(begin['command'])-127),('reserved',112,1),\n        ('initializer-return',72,0),('initializer-workspace',80,8191),\n        ('old-registry-return',88,0),('old-registry-event-size',96,255),('extra',104,1)):\n        word('program-begin-'+label,begin,at,value)\n    for label,at,value in (\n        ('phase',SC['I_PHASE'],63),('peer',SC['I_PEER'],19),('pending',SC['I_PENDING'],0),\n        ('argument',SC['I_ARG0'],0),('operation',SC['I_OP'],1),('digits',SC['I_DIGITS'],639),\n        ('event-peer',2048+48,18),('event-size',2048+208,511)):\n        word('program-initializer-'+label,begin,128+at,value)\n    prior=128+struct.unpack_from('<Q',begin['command'],80)[0]\n    for label,index,value in (\n        ('magic',0,0),('action',1,0),('peer',6,10),('pending',7,0),\n        ('child-kind',9,1),('argument',24,0),('mode',30,3),('reserved',31,1)):\n        word('program-preceding-pure-'+label,begin,prior+8*index,value)\n    for label,at,value in (\n        ('return',72,0),('role',80,2),('action',128+8,2),('sequence',128+32,0),\n        ('command',128+40,0),('root',128+160,0),('handle',128+168,0),('reserved',128+224,1)):\n        word('program-borrow-'+label,borrow,at,value)\n    for label,at,value in (\n        ('return',72,0),('role',80,2),('lease',128+16,0),('flags',128+48,2),\n        ('payload-at',128+88,MAX),('payload-size',128+96,8388609),('reserved',128+120,1)):\n        word('program-wire-'+label,wire,at,value)\n    frame=128\n    for label,at,value in (\n        ('status',72,1),('role',80,0),('stdout-size',88,0),('stderr-size',96,127),\n        ('magic',frame,0),('lease',frame+16,0),('request',frame+24,0),\n        ('mode',frame+32,3),('kind',frame+40,2),('domain',frame+48,2),\n        ('frame-size',frame+72,0),('receipt-at',frame+80,0),('core-at',frame+96,0),\n        ('core-size',frame+104,8388609),('receipt-magic',frame+256,0),\n        ('receipt-lease',frame+272,0),('receipt-input-kind',frame+288,2),\n        ('receipt-source-version',frame+296,0),('receipt-core-size',frame+320,0),\n        ('receipt-owner',frame+400,0),('receipt-reserved',frame+448,1)):\n        word('program-child-'+label,child,at,value)\n    terminal=128+struct.unpack_from('<Q',child['command'],88)[0]\n    word('program-child-terminal-status',child,terminal+32,1)\n    word('program-child-terminal-extent',child,terminal+64,0)\n    for label,at,value in (\n        ('return',72,0),('foreign',128+72,0),('output',128+80,0),\n        ('sequence',128+32,0),('phase',128+240,0)):\n        word('program-reserve-'+label,reserve,at,value)\n    for label,at,value in (\n        ('return',72,0),('output-size',88,0),('work-size',96,0),('magic',128,0),\n        ('nodes',136,0),('extent',152,0),('wire-length',168,0),('root-count',176,0),('reserved',184,1)):\n        word('program-decoder-'+label,decoded,at,value)\n    decoder_out=struct.unpack_from('<Q',decoded['command'],88)[0]\n    word('program-decoder-depth',decoded,128+decoder_out+56,65)\n    for label,at,value in (\n        ('return',72,0),('role',80,0),('extent',88,0),('config',128+128,0),\n        ('saved-config',128+1024,0),('saved-arena',128+1152,0),\n        ('event-magic',128+2048,0),('action',128+2056,2),\n        ('sequence',128+2080,0),('graph-lease',128+2088,0),\n        ('phase',128+2216,30),('reserved',128+2224,1)):\n        word('program-datagraph-'+label,dg,at,value)\n    for label,at,value in (\n        ('return',72,0),('action',128+8,5),('sequence',128+32,0),('command',128+40,0),\n        ('lease',128+48,0),('graph-size',128+56,0),('handle',128+168,0),('issued',128+192,0)):\n        word('program-import-'+label,bound,at,value)\n    faults.append(('program-import-scalar-bytes',bound,\n        lambda s,r,w:s.__setitem__(-1,s[-1]^1),True,None,None))\n    def record_word(label,relative,value):\n        def change(s,r,w):\n            root=struct.unpack_from('<Q',r,128+160)[0]\n            at=struct.unpack_from('<Q',s,root*64+8)[0]\n            struct.pack_into('<Q',s,at+relative,value)\n        faults.append((label,record_borrow,change,True,None,None))\n    for label,at,value in (\n        ('magic',0,0),('version',8,0),('invocation',16,0),('call',24,0),\n        ('old-pending',32,MAX),('tree',48,2),('frame-size',56,0)):\n        record_word('program-record-'+label,at,value)\n    for snapshot in (begin,child,decoded):\n        faults.append(('program-wrong-kernel-'+str(snapshot['mode']),snapshot,lambda s,r,w:None,True,\n            'program-output' if snapshot['role']=='program-input' else 'program-input',None))\n    faults.append(('program-short-workspace',begin,lambda s,r,w:None,False,None,8191))\n    # A completed native route cannot be reused, even with its original frame.\n    final=next(r for r in PROGRAM_CAPTURES if r['peer']==18 and r['event'][1]==0)\n    faults.append(('program-terminal-reuse',{**final,'workspace':final['after']},\n        lambda s,r,w:None,True,None,None))\n    inventory=[row[0] for row in faults]\n    assert len(faults)==117 and len(inventory)==len(set(inventory))\n    planned=1+len(faults)+3\n    save(OUT/'program-protocol-inventory.json',dict(complete_original_constructor=1,\n        raw_actual_frame_mutations=inventory,private_actual_error_propagations=3,\n        planned_cases=planned,all_frames_from_this_group=True,zero_inherited_cases=True))\n    for args in faults:program_fault(*args)\n    for peer in (16,17,18):\n        snapshot=find(peer,4)\n        assert struct.unpack_from('<Q',snapshot['workspace'],PB_CONSTANTS['P_RETRY'])[0]==0\n        program_actual_error_control(snapshot,invalids[peer],\n            'program-private-actual-error-'+str(peer),references[peer])\n    save(OUT/'program-results.json',PROGRAM_RESULTS)\n"
